#include "object/coin_explode.hpp"

#include "math/random.hpp"
#include "object/coin.hpp"
#include "supertux/sector.hpp"

#include <array>

CoinExplode::CoinExplode(const Vector& pos, bool count_stats, const std::string& sprite) :
  m_sprite(sprite),
  position(pos),
  m_count_stats(count_stats)
{
}

void
CoinExplode::update(float )
{
  float mag = 100.0f; // Magnitude at which coins are thrown.
  float rand = 30.0f; // Max variation to be subtracted from the magnitude.

  // Each coin in the explosion has a different velocity. Only one half of
  // the fan is listed; every entry is thrown twice, once mirrored.
  static const std::array<Vector, 5> coin_velocities = {{
    { 2.5f, -4.5f }, { 2.f, -5.f },
    { 1.5f, -5.5f }, { 1.f, -6.f }, { 0.5f, -6.5f }
  }};

  for (const auto& vector : coin_velocities)
  {
    for (const float side : { 1.f, -1.f })
    {
      const Vector velocity = Vector(vector.x, vector.y * side) * (mag - gameRandom.randf(rand));
      Sector::get().add<HeavyCoin>(position, velocity, m_count_stats, m_sprite);
    }
  }

  remove_me();
}

void
CoinExplode::draw(DrawingContext &)
{
}
#include "object/coin_rain.hpp"

#include "math/random.hpp"
#include "object/coin.hpp"
#include "sprite/sprite.hpp"
#include "sprite/sprite_manager.hpp"
#include "supertux/sector.hpp"

static const float DROP_TIME = .1f; // Time duration between "drops" of coin rain.

CoinRain::CoinRain(const Vector& pos, bool emerge, bool count_stats, const std::string& sprite_path) :
  sprite(SpriteManager::current()->create(sprite_path)),
  m_sprite_path(sprite_path),
  position(pos),
  emerge_distance(0),
  timer(),
  counter(0),
  drop(0),
  m_count_stats(count_stats)
{
  if (emerge) {
    emerge_distance = static_cast<float>(sprite->get_height());
  }
}

void
CoinRain::update(float dt_sec)
{
  // First a single (untouchable) coin flies up above the sector.
  if (position.y > -32){
    float dist = -500 * dt_sec;
    position.y += dist;
    emerge_distance += dist;
  } // Then the first collectable coin drops from one of ten random positions.
  else if (counter==0){
    drop = gameRandom.rand(10);
    Sector::get().add<HeavyCoin>(Vector(position.x + 32.0f * static_cast<float>((drop < 5) ? -drop - 1 : drop - 4), -32.0f),
                                                              Vector(0, 0), m_count_stats, m_sprite_path);
    counter++;
    timer.start(DROP_TIME);
  } // Finally, the remaining coins drop in a determined but seemingly random order.
  else if (timer.check()){
    if (counter<10){
      drop += 7;
      if (drop >= 10) drop -=10;
      Sector::get().add<HeavyCoin>(Vector(position.x + 32.0f * static_cast<float>((drop < 5) ? -drop - 1 : drop - 4), -32.0f),
                                                                Vector(0, 0), m_count_stats, m_sprite_path);
      counter++;
      timer.start(DROP_TIME);
    } else {
      remove_me();
    }
  }
}

void
CoinRain::draw(DrawingContext& context)
{
  int layer;
  if (emerge_distance > 0) {
    layer = LAYER_OBJECTS - 5;
  } else {
    layer = LAYER_OBJECTS + 5;
  }
  sprite->draw(context.color(), position, layer);
}

