if (!is_grabbed()) {

    if (get_bbox().get_top() > Sector::get().get_height()) {
      remove_me();
    }

    Rectf icebox = get_bbox().grown(-1.f);
    icebox.set_bottom(get_bbox().get_bottom() + 8.f);
    m_on_ice = !Sector::get().is_free_of_tiles(icebox, true, Tile::ICE);

    bool in_water = !Sector::get().is_free_of_tiles(get_bbox(), true, Tile::WATER);
    m_physic.set_gravity_modifier(in_water ? 0.2f : 1.f);

    Rectf trampolinebox = get_bbox().grown(-1.f);
    trampolinebox.set_bottom(get_bbox().get_bottom() + 8.f);

    for (auto& trampoline : Sector::get().get_objects_by_type<Trampoline>()) {
      if (trampolinebox.overlaps(trampoline.get_bbox()) && !trampoline.is_grabbed() &&
        (glm::length((get_bbox().get_middle() - trampoline.get_bbox().get_middle())) >= 10.f) &&
        is_portable()) {
        trampoline.bounce();
        m_physic.set_velocity_y(-500.f);
      }
    }

    const float sector_gravity = Sector::get().get_gravity();

void
ViciousIvy::active_update(float dt_sec)
{
  WalkingBadguy::active_update(dt_sec);
  if (!m_frozen && !m_ignited)
  {
    bool in_water = !Sector::get().is_free_of_tiles(get_bbox(), true, Tile::WATER);

    Rectf watertopbox = get_bbox();
    watertopbox.set_top(get_bbox().get_bottom() - get_bbox().get_height()/3.f);
    Rectf wateroutbox = get_bbox();
    wateroutbox.set_bottom(get_bbox().get_top() + (2*get_bbox().get_height()/3.f));

    bool on_top_of_water = (!Sector::get().is_free_of_tiles(watertopbox, true, Tile::WATER) &&
      Sector::get().is_free_of_tiles(wateroutbox, true, Tile::WATER));

    Rectf floatbox = get_bbox();
    floatbox.set_bottom(get_bbox().get_bottom() + 8.f);

    const bool ignore_unisolid = on_top_of_water || m_physic.get_velocity_y() < 0.0f;
    bool float_here = (Sector::get().is_free_of_tiles(floatbox, ignore_unisolid)
                       && Sector::get().is_free_of(floatbox, (1 << COLGROUP_STATIC) | (1 << COLGROUP_MOVING_STATIC),

