cd /app; python3 - <<'EOF'
p='src/object/coin.cpp'
s=open(p).read()
s=s.replace('''  // Enable physics.
  m_col.set_movement(m_physic.get_movement(dt_sec));''','''  // In water, coins sink slowly regardless of how fast they entered it.
  const bool in_water = !Sector::get().is_free_of_tiles(get_bbox(), true, Tile::WATER);
  if (in_water)
  {
    static const float WATER_MAX_SINK_SPEED = 50.0f;
    static const float WATER_MAX_RISE_SPEED = 50.0f;
    static const float WATER_MAX_DRIFT_SPEED = 30.0f;

    m_physic.set_gravity_modifier(0.2f);
    m_physic.set_velocity_x(math::clamp(m_physic.get_velocity_x(), -WATER_MAX_DRIFT_SPEED, WATER_MAX_DRIFT_SPEED));
    m_physic.set_velocity_y(math::clamp(m_physic.get_velocity_y(), -WATER_MAX_RISE_SPEED, WATER_MAX_SINK_SPEED));
  }
  else
  {
    m_physic.set_gravity_modifier(1.0f);
  }

  // Enable physics.
  m_col.set_movement(m_physic.get_movement(dt_sec));''')
s=s.replace('''    } else {
      m_physic.set_velocity_y(0);
    }''','''    } else {
      m_physic.set_velocity_y(0);
      m_physic.set_velocity_x(0);
    }''')
s=s.replace('#include "supertux/sector.hpp"\n','#include "supertux/sector.hpp"\n#include "supertux/tile.hpp"\n#include "math/util.hpp"\n',1)
open(p,'w').write(s)
p='src/object/coin_explode.cpp'
s=open(p).read()
s=s.replace('Vector(vector.x, vector.y * side)','Vector(vector.x * side, vector.y)')
open(p,'w').write(s)
EOF
